<?php defined('NX_ROOT') || exit; $draft = $run['status'] === 'Draft'; ?>
<div class="mx-auto max-w-[1300px]">
  <div class="mb-5 flex flex-wrap items-center gap-3">
    <div class="flex-1"><h1 class="text-xl font-semibold tracking-tight"><?= e($title) ?></h1><p class="mt-1 text-sm text-muted"><?= count($slips) ?> employees · <?= badge($run['status'], ['Draft' => 'slate', 'Approved' => 'blue', 'Paid' => 'green'][$run['status']] ?? 'slate') ?></p></div>
    <?php if ($draft && can('payroll', 'edit')): ?><button class="btn btn-secondary" data-action="<?= e(url('/payroll/' . $run['id'] . '/recalculate')) ?>"><?= icon('refresh-cw') ?>Recalculate</button><?php endif; ?>
    <?php if ($draft && can('payroll', 'approve')): ?><button class="btn btn-primary" data-action="<?= e(url('/payroll/' . $run['id'] . '/approve')) ?>" data-confirm="Approve and lock this payroll?"><?= icon('stamp') ?>Approve</button><?php endif; ?>
    <?php if ($run['status'] === 'Approved' && can('payroll', 'approve')): ?><button class="btn btn-primary" data-action="<?= e(url('/payroll/' . $run['id'] . '/paid')) ?>" data-confirm="Mark salaries as paid? A salary expense will be recorded."><?= icon('banknote') ?>Mark as paid</button><?php endif; ?>
    <?php if (!$draft && can('payroll', 'approve')): ?><button class="btn btn-secondary" data-action="<?= e(url('/payroll/' . $run['id'] . '/email')) ?>" data-confirm="E-mail every employee their payslip?"><?= icon('send') ?>E-mail payslips</button><?php endif; ?>
  </div>
  <div class="mb-5 grid gap-3 sm:grid-cols-3"><div class="card p-4"><p class="text-xs text-muted">Gross</p><p class="mt-1 text-xl font-semibold"><?= e(money((float) $run['total_gross'])) ?></p></div><div class="card p-4"><p class="text-xs text-muted">Deductions</p><p class="mt-1 text-xl font-semibold"><?= e(money((float) $run['total_deductions'])) ?></p></div><div class="card p-4"><p class="text-xs text-muted">Net pay</p><p class="mt-1 text-xl font-semibold"><?= e(money((float) $run['total_net'])) ?></p></div></div>
  <section class="card overflow-x-auto"><table class="data-table text-[13px]"><thead><tr><th>Employee</th><th class="text-right">Paid days</th><th class="text-right">LOP</th><th class="text-right">Gross</th><th class="text-right">PF</th><th class="text-right">ESI</th><th class="text-right">PT</th><th class="text-right">TDS</th><th class="text-right">Other</th><th class="text-right">Net</th><th></th></tr></thead><tbody>
    <?php foreach ($slips as $s): ?>
      <tr x-data="{ edit: false }"><td><span class="font-medium"><?= e($s['name']) ?></span><span class="block text-xs text-muted"><?= e($s['designation'] ?: $s['employee_code']) ?></span></td>
        <td class="text-right tabular-nums"><?= (float) $s['paid_days'] ?>/<?= (int) $s['working_days'] ?></td><td class="text-right tabular-nums <?= (float) $s['lop_days'] ? 'text-red-600' : '' ?>"><?= (float) $s['lop_days'] ?></td>
        <td class="text-right tabular-nums"><?= e(number_format((float) $s['gross'], 2)) ?></td><td class="text-right tabular-nums"><?= e(number_format((float) $s['pf'], 0)) ?></td><td class="text-right tabular-nums"><?= e(number_format((float) $s['esi'], 0)) ?></td><td class="text-right tabular-nums"><?= e(number_format((float) $s['pt'], 0)) ?></td>
        <td class="text-right tabular-nums"><span x-show="!edit"><?= e(number_format((float) $s['tds'], 0)) ?></span><input x-show="edit" x-cloak form="adj-<?= (int) $s['id'] ?>" name="tds" type="number" step="any" min="0" class="input input-sm ml-auto w-24 text-right" value="<?= e((string) (float) $s['tds']) ?>" aria-label="TDS for <?= e($s['name']) ?>"></td>
        <td class="text-right tabular-nums"><span x-show="!edit"><?= e(number_format((float) $s['other_deductions'], 0)) ?></span><input x-show="edit" x-cloak form="adj-<?= (int) $s['id'] ?>" name="other_deductions" type="number" step="any" min="0" class="input input-sm ml-auto w-24 text-right" value="<?= e((string) (float) $s['other_deductions']) ?>" aria-label="Other deductions for <?= e($s['name']) ?>"></td>
        <td class="text-right font-medium tabular-nums"><?= e(number_format((float) $s['net'], 2)) ?></td>
        <td class="whitespace-nowrap text-right"><?php if ($draft && can('payroll', 'edit')): ?><form id="adj-<?= (int) $s['id'] ?>" method="post" action="<?= e(url('/payroll/payslips/' . $s['id'])) ?>" data-ajax class="inline"><?= csrf_field() ?><button x-show="edit" x-cloak class="btn btn-primary btn-sm" type="submit" aria-label="Save deductions"><?= icon('check') ?></button></form><button x-show="!edit" type="button" class="btn btn-ghost btn-sm" @click="edit = true" title="Edit TDS / other deductions"><?= icon('pencil') ?></button><?php endif; ?><a class="btn btn-ghost btn-sm" href="<?= e(url('/payroll/payslips/' . $s['id'] . '/pdf')) ?>" title="Payslip PDF"><?= icon('download') ?></a></td></tr>
    <?php endforeach; ?>
    <?php if (!$slips): ?><tr><td colspan="11" class="py-8 text-center text-muted">No employees with a salary for this month. Set "Monthly salary (CTC)" on employee records.</td></tr><?php endif; ?>
  </tbody></table></section>
</div>
